// Generated by scripts/build-assets.mjs

/* ===== upload-upload-panel.js ===== */
(function initUploadPanel() {
  const root = document.getElementById("upload-panel-root");
  if (!root) return;

  const appId = root.dataset.appId || "";
  const selectedFile = root.dataset.selectedFile || "";

  root.innerHTML = `
    <form id="upload-file-form" class="grid gap-2">
      <label class="text-[11px] text-slate-400">上传文件到当前目录</label>
      <input type="file" name="file" class="text-xs text-slate-200" />
      <button type="submit" class="rounded-md border border-sky-500/40 bg-sky-500/15 px-3 py-1.5 text-xs text-sky-100">上传</button>
      <p id="upload-panel-status" class="text-[11px] text-slate-400"></p>
    </form>
    ${
      selectedFile
        ? `<button type="button" id="upload-delete-btn" class="mt-2 rounded-md border border-rose-500/35 bg-rose-500/10 px-3 py-1.5 text-xs text-rose-100">删除当前文件</button>`
        : ""
    }
  `;

  const statusEl = document.getElementById("upload-panel-status");
  const form = document.getElementById("upload-file-form");
  const deleteBtn = document.getElementById("upload-delete-btn");

  function setStatus(text, isError) {
    if (!statusEl) return;
    statusEl.textContent = text || "";
    statusEl.className = isError
      ? "text-[11px] text-rose-300"
      : "text-[11px] text-slate-400";
  }

  form?.addEventListener("submit", async (event) => {
    event.preventDefault();
    const input = form.querySelector('input[type="file"]');
    const file = input?.files?.[0];
    if (!file) {
      setStatus("请选择文件", true);
      return;
    }
    const body = new FormData();
    body.append("file", file);
    if (selectedFile) {
      const parent = selectedFile.includes("/")
        ? selectedFile.slice(0, selectedFile.lastIndexOf("/"))
        : "";
      if (parent) body.append("dir", parent);
    }
    setStatus("上传中…");
    try {
      const response = await fetch(`/api/upload/${encodeURIComponent(appId)}`, {
        method: "POST",
        body,
      });
      const payload = await response.json().catch(() => ({}));
      if (!response.ok) {
        throw new Error(payload.error || `上传失败 (${response.status})`);
      }
      setStatus("上传成功，正在刷新…");
      window.location.reload();
    } catch (error) {
      setStatus(error?.message || "上传失败", true);
    }
  });

  deleteBtn?.addEventListener("click", async () => {
    if (!selectedFile || !window.confirm(`确认删除 ${selectedFile}？`)) return;
    setStatus("删除中…");
    try {
      const response = await fetch(
        `/api/upload/${encodeURIComponent(appId)}?path=${encodeURIComponent(selectedFile)}`,
        { method: "DELETE" },
      );
      const payload = await response.json().catch(() => ({}));
      if (!response.ok) {
        throw new Error(payload.error || `删除失败 (${response.status})`);
      }
      setStatus("已删除，正在刷新…");
      window.location.href = `/apps/upload/${encodeURIComponent(appId)}`;
    } catch (error) {
      setStatus(error?.message || "删除失败", true);
    }
  });
})();

;
